"""Small helpers for emitting deterministic Vdbench parameter files."""

from __future__ import annotations

from pathlib import Path
from typing import Iterable

from .layout import Bucket


def config_header(title: str, *, check_skew: bool = False) -> list[str]:
    lines = [
        f"* {title}",
        "* Generated by SYSU_workload scripts; client hd= definitions are intentionally deferred.",
        "",
        "data_errors=1",
        "create_anchors=yes",
        "messagescan=no",
    ]
    if check_skew:
        lines.append("abort_failed_skew=2")
    lines.append("")
    return lines


def render_fsd_lines(buckets: Iterable[Bucket]) -> list[str]:
    lines = ["fsd=default,depth=1,width=1,shared=yes,openflags=o_direct"]
    lines.extend(
        f"fsd={bucket.name},anchor={bucket.anchor},files={bucket.files},size={bucket.size_mib}m"
        for bucket in buckets
    )
    lines.append("")
    return lines


def render_prepare_config(title: str, buckets: list[Bucket], threads: int) -> str:
    lines = config_header(f"{title} - prepare only")
    lines.extend(render_fsd_lines(buckets))
    prep_names = []
    for bucket in buckets:
        name = f"prep_{bucket.name.removeprefix('fsd_')}"
        prep_names.append(name)
        lines.append(f"fwd={name},fsd={bucket.name},operation=read,threads={threads}")
    joined = ",".join(prep_names)
    lines.extend(
        [
            "",
            f"rd=prepare_clean,fwd=({joined}),format=(clean,only),fwdrate=max",
            f"rd=prepare_create,fwd=({joined}),format=(restart,only),fwdrate=max",
            "",
        ]
    )
    return "\n".join(lines)


def fwd_line(
    *,
    name: str,
    bucket: Bucket,
    operation: str,
    fileio: str,
    threads: int,
    skew: str,
    xfersize: str = "4m",
) -> str:
    return (
        f"fwd={name},fsd={bucket.name},operation={operation},fileio={fileio},"
        f"fileselect=random,xfersize={xfersize},threads={threads},skew={skew}"
    )


def rd_line(*, name: str, fwds: list[str], rate: str, elapsed: int) -> str:
    return (
        f"rd={name},fwd=({','.join(fwds)}),fwdrate={rate},"
        f"elapsed={elapsed},interval=1"
    )


def write_config(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")
